(4054766, 579732, 59840, '<td valign="top">I don''t see the point of the Barnum and Bailey-style font.</td>', 'I don''t see the point of the Barnum and Bailey-style font.', '2007-09-03 22:34:47.000000', NULL, 1),
(4054771, 578914, 45475, '<td valign="top">Good solid inspirational quote. The image could use a bit more contrast though and the O and P above gets lost in the background unfortunately. Maybe justifying right would have helped?</td>', 'Good solid inspirational quote. The image could use a bit more contrast though and the O and P above gets lost in the background unfortunately. Maybe justifying right would have helped?', '2007-09-03 22:36:39.000000', NULL, 1),
(4054774, 580555, 41337, '<td valign="top">This subject just isn''t going to do well in the challenge but to help improve it make the lighing more dramatic by making it darker and more moody. I would shoot this in a dark room with a spotlight from above giving the toy and hammock shape.</td>', 'This subject just isn''t going to do well in the challenge but to help improve it make the lighing more dramatic by making it darker and more moody. I would shoot this in a dark room with a spotlight from above giving the toy and hammock shape.', '2007-09-03 22:37:44.000000', NULL, 1),
(4054779, 580701, 41337, '<td valign="top">Good choice to convey the message. If the lighting was less harsh this would do better.</td>', 'Good choice to convey the message. If the lighting was less harsh this would do better.', '2007-09-03 22:39:07.000000', NULL, 1),
(4054783, 579575, 45475, '<td valign="top">Clever layout design :)</td>', 'Clever layout design :)', '2007-09-03 22:40:27.000000', NULL, 1),
(4054790, 580721, 41337, '<td valign="top">Good fit for the challenge. The fireworks are good but probably would go over better with the voters had it been on the verge of bursting out of the frame.</td>', 'Good fit for the challenge. The fireworks are good but probably would go over better with the voters had it been on the verge of bursting out of the frame.', '2007-09-03 22:42:35.000000', NULL, 1),
(4054791, 580278, 45475, '<td valign="top">Such a dramatic shot of the clouds! Nicely captured :)</td>', 'Such a dramatic shot of the clouds! Nicely captured :)', '2007-09-03 22:42:42.000000', NULL, 1),
(4054807, 580700, 41337, '<td valign="top">Nice entry. The font layout is good but I don''t like the bevel especially with the smaller text.</td>', 'Nice entry. The font layout is good but I don''t like the bevel especially with the smaller text.', '2007-09-03 22:47:10.000000', NULL, 1),
(4054812, 579597, 45475, '<td valign="top">And don''t forget: "Lose weight fast!". Yeah, I like your take on the challenge.</td>', 'And don''t forget: "Lose weight fast!". Yeah, I like your take on the challenge.', '2007-09-03 22:48:12.000000', NULL, 1),
(4054818, 581075, 41337, '<td valign="top">You are just asking for it. Funny though!</td>', 'You are just asking for it. Funny though!', '2007-09-03 22:50:34.000000', NULL, 1),
(4054821, 580844, 45475, '<td valign="top">They''re having a ball, it''s a great fit :) Nice work!</td>', 'They''re having a ball, it''s a great fit :) Nice work!', '2007-09-03 22:51:21.000000', NULL, 1),
(4054831, 579872, 45475, '<td valign="top">Great night shot of a wonderful building, but it''s not really the type of imagery that would inspire me exactly.</td>', 'Great night shot of a wonderful building, but it''s not really the type of imagery that would inspire me exactly.', '2007-09-03 22:54:31.000000', NULL, 1),
(4054844, 579806, 45475, '<td valign="top">Strange but interesting. I''m intrigued by the person sitting outside left of frame. You must have left them there for a reason, I''m just trying to figure out why....</td>', 'Strange but interesting. I''m intrigued by the person sitting outside left of frame. You must have left them there for a reason, I''m just trying to figure out why....', '2007-09-03 22:57:56.000000', NULL, 1),
(4054847, 580666, 32033, '<td valign="top">neat</td>', 'neat', '2007-09-03 22:58:08.000000', NULL, 1),
(4054850, 581075, 33446, '<td valign="top">I don''t know about the motivational concept but it did make me laugh and it''s a good picture.</td>', 'I don''t know about the motivational concept but it did make me laugh and it''s a good picture.', '2007-09-03 22:58:50.000000', NULL, 1),
(4054863, 580275, 45475, '<td valign="top">If only.... ;) Fun idea, well done!</td>', 'If only.... ;) Fun idea, well done!', '2007-09-03 23:01:24.000000', NULL, 1),
(4054887, 581090, 66267, '<td valign="top">With my assistance, a lot.</td>', 'With my assistance, a lot.', '2007-09-03 23:07:29.000000', NULL, 1),
(4054895, 580701, 45475, '<td valign="top">Good motivational quote and nice layout, but the image is not conveying the message to me at all. But then, I''m probably just a thickie ;)</td>', 'Good motivational quote and nice layout, but the image is not conveying the message to me at all. But then, I''m probably just a thickie ;)', '2007-09-03 23:08:51.000000', NULL, 1),
(4054900, 580964, 45475, '<td valign="top">... and this is motivating me how?? :D Quite like the funky editing though.</td>', '... and this is motivating me how?? :D Quite like the funky editing though.', '2007-09-03 23:10:10.000000', NULL, 1);
