(4061564, 580901, 53998, '<td valign="top">Yup, Motivates me, great composition, really feel the title too. I think it would even look good if it had less sky in it too, more like a 24X36in crop rather than a square crop; Nonetheless a great shot!</td>', 'Yup, Motivates me, great composition, really feel the title too. I think it would even look good if it had less sky in it too, more like a 24X36in crop rather than a square crop; Nonetheless a great shot!', '2007-09-05 13:26:36.000000', NULL, 1),
(4061567, 579608, 53998, '<td valign="top">Great idea! without the title, it will still be a good photo, the bench really stands out after reading the title.</td>', 'Great idea! without the title, it will still be a good photo, the bench really stands out after reading the title.', '2007-09-05 13:28:03.000000', NULL, 1),
(4061568, 580700, 53998, '<td valign="top">I feel it, great composition, great title!</td>', 'I feel it, great composition, great title!', '2007-09-05 13:29:00.000000', NULL, 1),
