(4073152, 579560, 41675, '<td valign="top">I like the image and lighting. The teamwork heading works, but for the life of me, I don''t understand how your subheading fits with it. Hmmm.</td>', 'I like the image and lighting. The teamwork heading works, but for the life of me, I don''t understand how your subheading fits with it. Hmmm.', '2007-09-08 20:56:42.000000', NULL, 1),
(4073158, 579770, 41675, '<td valign="top">Lol - Oh my gosh! How cute is this!! Lol I love it. So very sweet. I truly hope this finishes in the top three.</td>', 'Lol - Oh my gosh! How cute is this!! Lol I love it. So very sweet. I truly hope this finishes in the top three.', '2007-09-08 20:58:08.000000', NULL, 1),
(4073159, 579021, 41675, '<td valign="top">An amusing tongue-in-cheek entry.</td>', 'An amusing tongue-in-cheek entry.', '2007-09-08 20:58:49.000000', NULL, 1),
(4073163, 578944, 41675, '<td valign="top">Nice image. I like the font for the heading. A little too much kearning between the sub-heading, but that''s just my taste.</td>', 'Nice image. I like the font for the heading. A little too much kearning between the sub-heading, but that''s just my taste.', '2007-09-08 21:00:31.000000', NULL, 1),
(4073168, 580488, 41675, '<td valign="top">LOL - love the photo and the saying below the header. Not so crazy about the header iself. Perhaps if is were spead out a little bit more. The italics make it seem "squished."</td>', 'LOL - love the photo and the saying below the header. Not so crazy about the header iself. Perhaps if is were spead out a little bit more. The italics make it seem "squished."', '2007-09-08 21:02:29.000000', NULL, 1),
(4073188, 580858, 41675, '<td valign="top">I like the image. It ties in well with your heading. Nicely done. With a bit more light or color contrast on the image, I would have scored it higher.</td>', 'I like the image. It ties in well with your heading. Nicely done. With a bit more light or color contrast on the image, I would have scored it higher.', '2007-09-08 21:10:30.000000', NULL, 1),
(4073193, 580805, 41675, '<td valign="top">Good image and header. I like your use of gradient and sans serif font choice. I do wonder how the sub headinggs would look in a thinner sans serif font like optima or maybe century gothic. I''m not sure the cursive font works well with "stronger."</td>', 'Good image and header. I like your use of gradient and sans serif font choice. I do wonder how the sub headinggs would look in a thinner sans serif font like optima or maybe century gothic. I''m not sure the cursive font works well with "stronger."', '2007-09-08 21:13:08.000000', NULL, 1),
(4073204, 580006, 41675, '<td valign="top">Hmmm, interesting image, yet for me, not very motivational. The left hand side of the lips looks overly done with the lipstick compared to the shape of the lips on the right. Point for creativity though.</td>', 'Hmmm, interesting image, yet for me, not very motivational. The left hand side of the lips looks overly done with the lipstick compared to the shape of the lips on the right. Point for creativity though.', '2007-09-08 21:20:13.000000', NULL, 1),
