(4075150, 581077, 30508, '<td valign="top">I really love this.  What a great find, and very well captured.  Your composition really echos the message of your quote.</td>', 'I really love this.  What a great find, and very well captured.  Your composition really echos the message of your quote.', '2007-09-09 15:15:31.000000', NULL, 1),
(4075153, 581026, 30508, '<td valign="top">Nice subject and composition.  The text seems a little detached where you have placed it though.</td>', 'Nice subject and composition.  The text seems a little detached where you have placed it though.', '2007-09-09 15:16:41.000000', NULL, 1),
(4075157, 579792, 30508, '<td valign="top">Great expression on the cattle.  The big, bold text certainly does fit the message.  Better lighting would be my only suggestion for improvement.</td>', 'Great expression on the cattle.  The big, bold text certainly does fit the message.  Better lighting would be my only suggestion for improvement.', '2007-09-09 15:19:12.000000', NULL, 1),
(4075162, 580891, 30508, '<td valign="top">Lovely image, beautifully composed and presented.  I wish the text had more relevance to the image, though.</td>', 'Lovely image, beautifully composed and presented.  I wish the text had more relevance to the image, though.', '2007-09-09 15:21:24.000000', NULL, 1),
(4075163, 580984, 30508, '<td valign="top">Simply lovely.  Good choice of quote to match the image (or vice versa).</td>', 'Simply lovely.  Good choice of quote to match the image (or vice versa).', '2007-09-09 15:22:04.000000', NULL, 1),
(4075165, 580805, 30508, '<td valign="top">Well done.  Great shot that really fits your message.</td>', 'Well done.  Great shot that really fits your message.', '2007-09-09 15:22:58.000000', NULL, 1),
(4075166, 580278, 1031, '<td valign="top">Very dynamic cloudscape -- I''d expect the plane to be bouncing around a lot.</td>', 'Very dynamic cloudscape -- I''d expect the plane to be bouncing around a lot.', '2007-09-09 15:24:12.000000', NULL, 1),
