(4075774, 580924, 41337, '<td valign="top">I''m not sure I like the script font you used but I like the photo and the concept. Good luck.</td>', 'I''m not sure I like the script font you used but I like the photo and the concept. Good luck.', '2007-09-09 21:16:39.000000', NULL, 1),
(4075781, 579575, 41337, '<td valign="top">The photo is a bit bland particularly the lighting but it does connect well with the quote. Good layout. Not sure I like the green though.</td>', 'The photo is a bit bland particularly the lighting but it does connect well with the quote. Good layout. Not sure I like the green though.', '2007-09-09 21:19:18.000000', NULL, 1),
