(4076921, 580491, 68546, '<td valign="top">Fantastic image Terry, I''m not too keen on the spacing of the bottem text but the image in this poster is excellent. Congrats on the great score as well</td>', 'Fantastic image Terry, I''m not too keen on the spacing of the bottem text but the image in this poster is excellent. Congrats on the great score as well', '2007-09-10 04:40:52.000000', NULL, 0),
(4076923, 578405, 28742, '<td valign="top">Way to go, RG! Congrats - great image, great finish and some cash to boot! :)</td>', 'Way to go, RG! Congrats - great image, great finish and some cash to boot! :)', '2007-09-10 04:41:41.000000', NULL, 0),
(4076926, 580338, 28742, '<td valign="top">Way to go, Barry! Congrats on 6th!! Awesome photo!</td>', 'Way to go, Barry! Congrats on 6th!! Awesome photo!', '2007-09-10 04:43:04.000000', NULL, 0),
(4076929, 580982, 28742, '<td valign="top">Congrats, Judi! A stunning sunset and well put together poster!</td>', 'Congrats, Judi! A stunning sunset and well put together poster!', '2007-09-10 04:44:31.000000', NULL, 0),
(4076944, 580654, 68035, '<td valign="top">Oh my goodness, I cannot believe this picture finished with the score it did.  Well If it is any consolation I thought it was great and am the person who scored it 8<br/> <br/>IMO - It met the challenge fully (unlike many which were great pictures but not motivational) the image complemented the title, the image itself was very good, nice unusal POV.  Good focus and the white sky that others did not like for me gave it a sense of light and hope...Ohhh and I liked the type and thought the cloud like bubble worked well<br/> <br/>In DPC there are always enough people to tell you why a picture is not good, but let me try and counterbalance that by saying this is a damned fine shot of which you should be proud<br/> <br/>Great job</td>', 'Oh my goodness, I cannot believe this picture finished with the score it did.  Well If it is any consolation I thought it was great and am the person who scored it 8 IMO - It met the challenge fully (unlike many which were great pictures but not motivational) the image complemented the title, the image itself was very good, nice unusal POV.  Good focus and the white sky that others did not like for me gave it a sense of light and hope...Ohhh and I liked the type and thought the cloud like bubble worked well In DPC there are always enough people to tell you why a picture is not good, but let me try and counterbalance that by saying this is a damned fine shot of which you should be proud Great job', '2007-09-10 05:21:33.000000', NULL, 0),
(4076962, 580700, 17513, '<td valign="top">great piccy..well done /congrats</td>', 'great piccy..well done /congrats', '2007-09-10 05:41:28.000000', NULL, 0),
